// Shared BCPSS term bank (one record per term, Spanish glosses, cognate status, per-band definitions).
// Generated by tools/build-bcpss-terms.mjs. Glosses are machine drafts until review_status is "human".

import { TERMS } from "../../../db/seeds/bcpss/v2/terms.mjs";

const BY_ID = new Map(TERMS.map((t) => [t.id, t]));
const fold = (s) =>
  String(s || "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase();

export const getTerm = (id) => BY_ID.get(id) || null;

export function searchTerms({ q = "", unit = "", band = "", limit = 50 } = {}) {
  const needle = fold(q).trim();
  const rows = TERMS.filter(
    (t) =>
      (!unit || t.units.includes(unit)) &&
      (!band || t.grade_bands.includes(band)) &&
      (!needle ||
        fold(t.term).includes(needle) ||
        Object.values(t.glosses).some((g) => fold(g.text).includes(needle))),
  );
  return { total: rows.length, terms: rows.slice(0, Math.min(Math.max(limit, 1), 200)) };
}
